insert into public.report_content (version_id, section, dimension_key, mode, title, body, sort_order) values
  (null, 'mbti_sintese', 'ISTJ', 'natural', 'Seu tipo: ISTJ', 'Você é a pessoa em quem se confia o que não pode falhar. Combina atenção ao concreto com senso de dever: o que você assume, sai — e sai conferido. Prefere método a improviso e resultado comprovado a promessa. O desafio é abrir espaço para o jeito novo antes de ter certeza de que ele funciona.', 1),
  (null, 'mbti_sintese', 'ISFJ', 'natural', 'Seu tipo: ISFJ', 'Você cuida sem alarde. Repara no que os outros precisam antes de pedirem e sustenta a rotina que mantém tudo de pé, normalmente sem receber crédito por isso. Sua lealdade é longa. O desafio é dizer não e pedir o que você precisa, em vez de esperar que percebam.', 2),
  (null, 'mbti_sintese', 'INFJ', 'natural', 'Seu tipo: INFJ', 'Você junta sensibilidade com direção. Enxerga o que move as pessoas e costuma ter uma ideia clara de onde tudo aquilo deveria chegar. Trabalha melhor com propósito à vista. O desafio é não se cobrar por um ideal que ninguém além de você combinou de perseguir.', 3),
  (null, 'mbti_sintese', 'INTJ', 'natural', 'Seu tipo: INTJ', 'Você pensa em sistema e a longo prazo. Vê o problema inteiro, monta a estratégia e a executa com independência. Autonomia, para você, não é conforto: é condição. O desafio é levar as pessoas junto, porque uma boa estratégia sem adesão não acontece.', 4),
  (null, 'mbti_sintese', 'ISTP', 'natural', 'Seu tipo: ISTP', 'Você entende as coisas mexendo nelas. Mantém a calma no problema técnico e no aperto, e resolve com economia de movimento. Discurso longo te cansa. O desafio é comunicar o que você está fazendo — muita gente só descobre depois de pronto.', 5),
  (null, 'mbti_sintese', 'ISFP', 'natural', 'Seu tipo: ISFP', 'Você vive pelo que sente ser certo, com discrição. Tem sensibilidade estética e prática, e prefere mostrar por gesto a defender por argumento. O desafio é se posicionar quando algo importante para você está em jogo, em vez de sair de cena.', 6),
  (null, 'mbti_sintese', 'INFP', 'natural', 'Seu tipo: INFP', 'Você é movido por coerência interna. Tem um senso forte do que importa e uma capacidade rara de enxergar o potencial das pessoas. O desafio é a distância entre o ideal e o possível: ela cobra caro quando você a transforma em cobrança contra si mesmo.', 7),
  (null, 'mbti_sintese', 'INTP', 'natural', 'Seu tipo: INTP', 'Você quer entender antes de agir. Desmonta o problema, encontra a inconsistência que ninguém viu e reconstrói por conta própria. O desafio é fechar: em algum momento a análise precisa virar decisão, mesmo faltando peça.', 8),
  (null, 'mbti_sintese', 'ESTP', 'natural', 'Seu tipo: ESTP', 'Você lê a situação rápido e age. É quem resolve na hora, negocia bem e não trava diante do imprevisto. Energia não falta. O desafio é a consequência de médio prazo — a saída rápida de hoje às vezes é o problema de daqui a três meses.', 9),
  (null, 'mbti_sintese', 'ESFP', 'natural', 'Seu tipo: ESFP', 'Você traz vida para onde chega. Presente, caloroso e prático, resolve pelo contato direto e faz as pessoas se sentirem à vontade. O desafio é o que não dá retorno imediato: planejamento e tarefa chata pedem uma disciplina que não vem por empolgação.', 10),
  (null, 'mbti_sintese', 'ENFP', 'natural', 'Seu tipo: ENFP', 'Você enxerga possibilidade em tudo e contagia. Conecta pessoas e ideias com facilidade e abre caminhos que ninguém tinha visto. O desafio é a continuidade: começar é fácil para você, terminar exige um combinado com você mesmo.', 11),
  (null, 'mbti_sintese', 'ENTP', 'natural', 'Seu tipo: ENTP', 'Você pensa questionando. Encontra a brecha do argumento, propõe o ângulo que ninguém considerou e gosta do desafio intelectual pelo desafio. O desafio é escolher: nem toda boa ideia merece ser perseguida, e dispersão custa mais do que parece.', 12),
  (null, 'mbti_sintese', 'ESTJ', 'natural', 'Seu tipo: ESTJ', 'Você organiza e faz acontecer. Define o que precisa ser feito, por quem e até quando, e cobra o cumprimento. Estrutura, para você, é o que permite escala. O desafio é o caso particular que não cabe na regra — e que às vezes é o mais importante.', 13),
  (null, 'mbti_sintese', 'ESFJ', 'natural', 'Seu tipo: ESFJ', 'Você mantém as pessoas juntas. Percebe as necessidades do grupo, cuida do combinado e do clima, e cria o ambiente onde os outros produzem. O desafio é separar a sua responsabilidade da dos outros: você não precisa carregar tudo para o time funcionar.', 14),
  (null, 'mbti_sintese', 'ENFJ', 'natural', 'Seu tipo: ENFJ', 'Você desenvolve gente. Enxerga o potencial de cada um, comunica com clareza e mobiliza em torno de um objetivo comum. Liderança, para você, é sobre pessoas. O desafio é lembrar de si: cuidar de todo mundo tem um custo que você costuma pagar calado.', 15),
  (null, 'mbti_sintese', 'ENTJ', 'natural', 'Seu tipo: ENTJ', 'Você conduz. Define o rumo, organiza os recursos e assume a responsabilidade pelo resultado, inclusive quando dá errado. Decisão difícil não te paralisa. O desafio é o ritmo — o seu é mais rápido que o da maioria, e nem todo mundo consegue acompanhar.', 16),
  (null, 'mbti_eixo', 'E', 'natural', null, '**Extroversão (E).** Você se orienta para fora. Pensa falando, resolve conversando, e costuma descobrir o que acha de um assunto no meio da frase. Ambiente com gente e movimento te abastece; tempo demais sozinho vai tirando o seu gás.', 17),
  (null, 'mbti_trabalho', 'E', 'natural', null, '**Extroversão no trabalho.** Você rende em times, reuniões e conversas de corredor. Tende a responder rápido e a ocupar espaço na discussão. O risco é decidir no calor da conversa e não deixar silêncio suficiente para os mais reservados aparecerem.', 18),
  (null, 'mbti_relacoes', 'E', 'natural', null, '**Extroversão nas relações.** Você aproxima com facilidade e mantém uma rede ampla. As pessoas sabem o que você está pensando, porque você fala. Quem é mais fechado pode levar um tempo para acompanhar o seu ritmo de aproximação.', 19),
  (null, 'mbti_atencao', 'E', 'natural', null, '**Ponto cego da Extroversão.** Falar antes de pensar. Como o pensamento acontece em voz alta, o que era rascunho pode ser ouvido como decisão. Vale marcar explicitamente: “estou pensando alto, ainda não decidi”.', 20),
  (null, 'mbti_eixo', 'I', 'natural', null, '**Introversão (I).** Você se orienta para dentro. Processa antes de falar, e o que sai já vem trabalhado. Precisa de um tempo sozinho para recuperar energia, e isso não é timidez nem falta de interesse — é como o seu sistema recarrega.', 21),
  (null, 'mbti_trabalho', 'I', 'natural', null, '**Introversão no trabalho.** Você entrega bem em tarefas que exigem concentração contínua e costuma trazer contribuições mais maduras. Em reunião, pode perder espaço para quem fala primeiro — pedir a pauta antes muda bastante o seu rendimento.', 22),
  (null, 'mbti_relacoes', 'I', 'natural', null, '**Introversão nas relações.** Você tem poucos vínculos e profundos. Investe onde há reciprocidade e evita o convívio de superfície. Quem convive com você precisa aprender que silêncio, aí, não é sinal de problema.', 23),
  (null, 'mbti_atencao', 'I', 'natural', null, '**Ponto cego da Introversão.** Guardar demais. Como você resolve por dentro, os outros às vezes só descobrem a sua posição quando ela já virou decisão — e se sentem passados para trás sem que essa fosse a intenção.', 24),
  (null, 'mbti_eixo', 'S', 'natural', null, '**Sensação (S).** Você confia no concreto: no que dá para ver, medir e conferir. Repara em detalhes que passam batido e prefere partir do que já funcionou a apostar numa teoria bonita.', 25),
  (null, 'mbti_trabalho', 'S', 'natural', null, '**Sensação no trabalho.** Você é bom em execução, em processo e em pegar o erro antes que ele chegue ao cliente. Pede exemplo e passo a passo, e com razão. O risco é o excesso de apego ao “sempre foi assim” quando o contexto já mudou.', 26),
  (null, 'mbti_relacoes', 'S', 'natural', null, '**Sensação nas relações.** Você demonstra cuidado por atos concretos: lembra de datas, resolve o que precisa ser resolvido, aparece quando tem que aparecer. Palavras soltas sem gesto correspondente soam vazias para você.', 27),
  (null, 'mbti_atencao', 'S', 'natural', null, '**Ponto cego da Sensação.** Descartar cedo demais o que ainda não tem prova. Nem toda ideia sem dados é fantasia; algumas só ainda não tiveram chance. Vale separar “não funciona” de “ainda não testei”.', 28),
  (null, 'mbti_eixo', 'N', 'natural', null, '**Intuição (N).** Você lê padrões e possibilidades. Enxerga aonde as coisas podem chegar antes de conseguir explicar por quê, e se interessa mais pelo desenho geral do que pelo detalhe da execução.', 29),
  (null, 'mbti_trabalho', 'N', 'natural', null, '**Intuição no trabalho.** Você é forte em começo de coisa: enxergar o problema por um ângulo novo, propor caminho, conectar assuntos que pareciam separados. O risco é abandonar na metade, quando a novidade acaba e sobra o operacional.', 30),
  (null, 'mbti_relacoes', 'N', 'natural', null, '**Intuição nas relações.** Você percebe o que não foi dito e costuma acertar no pressentimento sobre pessoas. Também pode preencher lacunas com interpretação própria e reagir a uma intenção que ninguém teve.', 31),
  (null, 'mbti_atencao', 'N', 'natural', null, '**Ponto cego da Intuição.** Pular o concreto. Uma boa ideia sem os passos, os prazos e os números não sai do lugar — e a frustração que vem disso costuma ser atribuída aos outros, não à falta de aterrissagem.', 32),
  (null, 'mbti_eixo', 'T', 'natural', null, '**Pensamento (T).** Você decide por critério. Busca o que é coerente, justo e sustentável no argumento, mesmo quando a conclusão é desconfortável. Franqueza, para você, é uma forma de respeito.', 33),
  (null, 'mbti_trabalho', 'T', 'natural', null, '**Pensamento no trabalho.** Você segura conversas difíceis e decisões impopulares sem adoçar. É quem consegue apontar a falha no plano de que todo mundo gostou. O risco é tratar o efeito humano da decisão como assunto de outra pessoa.', 34),
  (null, 'mbti_relacoes', 'T', 'natural', null, '**Pensamento nas relações.** Você ajuda resolvendo: quando alguém traz um problema, sua reação natural é procurar a saída. Nem sempre é isso que a pessoa foi buscar, e perguntar “você quer ajuda ou quer desabafar?” resolve boa parte dos mal-entendidos.', 35),
  (null, 'mbti_atencao', 'T', 'natural', null, '**Ponto cego do Pensamento.** Confundir estar certo com estar bem resolvido. Uma decisão tecnicamente correta que ninguém aceita não foi implementada — e o custo disso é real, mesmo não aparecendo na planilha.', 36),
  (null, 'mbti_eixo', 'F', 'natural', null, '**Sentimento (F).** Você decide por valor e por impacto nas pessoas. Pesa quem será afetado, o que é coerente com o que você acredita, e como a decisão vai ser recebida. Harmonia, para você, faz parte do resultado.', 37),
  (null, 'mbti_trabalho', 'F', 'natural', null, '**Sentimento no trabalho.** Você percebe o clima antes dos outros e segura o time nos momentos ruins. É quem lembra que por trás do número tem gente. O risco é adiar a conversa dura até ela virar um problema maior do que era.', 38),
  (null, 'mbti_relacoes', 'F', 'natural', null, '**Sentimento nas relações.** Você acolhe bem e cria segurança em quem está por perto. Também absorve o estado emocional do ambiente, e pode sair de um dia difícil carregando o que era dos outros.', 39),
  (null, 'mbti_atencao', 'F', 'natural', null, '**Ponto cego do Sentimento.** Ceder para preservar a paz e cobrar depois, por dentro. O acordo que você não quis fazer mas fez para não criar atrito costuma voltar como ressentimento — e aí a conversa fica bem mais difícil do que seria no começo.', 40),
  (null, 'mbti_eixo', 'J', 'natural', null, '**Julgamento (J).** Você se organiza fechando. Gosta de decidir, planejar e riscar da lista. Assunto em aberto ocupa espaço na sua cabeça até ser resolvido, então você tende a resolver cedo.', 41),
  (null, 'mbti_trabalho', 'J', 'natural', null, '**Julgamento no trabalho.** Você entrega no prazo e costuma entregar antes. Estrutura, cronograma e definição são o seu terreno. O risco é fechar cedo demais, antes de a informação necessária existir, só para tirar o assunto da mesa.', 42),
  (null, 'mbti_relacoes', 'J', 'natural', null, '**Julgamento nas relações.** As pessoas sabem o que esperar de você, e isso vale muito. Combinado é combinado. Quem tem um jeito mais solto de viver pode sentir a sua organização como cobrança, mesmo quando não é.', 43),
  (null, 'mbti_atencao', 'J', 'natural', null, '**Ponto cego do Julgamento.** Tratar mudança de plano como falha de caráter. Às vezes o cenário mudou e o plano é que precisa mudar. Perguntar “o que mudou?” antes de “por que não cumpriram?” evita muito desgaste.', 44),
  (null, 'mbti_eixo', 'P', 'natural', null, '**Percepção (P).** Você se organiza mantendo aberto. Gosta de reunir informação, testar e decidir o mais tarde possível, porque fechar cedo parece desperdiçar opção. Improviso não te assusta.', 45),
  (null, 'mbti_trabalho', 'P', 'natural', null, '**Percepção no trabalho.** Você lida bem com imprevisto, cenário mutável e problema sem manual. Rende no fim, quando a pressão aperta. O risco é acumular pendência e transformar em rotina o que deveria ser exceção.', 46),
  (null, 'mbti_relacoes', 'P', 'natural', null, '**Percepção nas relações.** Você é fácil de conviver, aceita o que aparece e não engessa o outro. Quem depende de previsibilidade, no entanto, pode ler a sua flexibilidade como descompromisso.', 47),
  (null, 'mbti_atencao', 'P', 'natural', null, '**Ponto cego da Percepção.** Adiar a decisão até ela ser tomada pelo prazo. Não decidir também é uma escolha — só que feita sem você, e normalmente pior do que a que você teria feito com uma semana de antecedência.', 48);
